def process(seq,coords):
    # Identify 9-runs; recolor length <=3 if any 4 exists elsewhere in line, and one side is a 4 (or boundary)
    has4=any(v==4 for v in seq)
    if not has4:return
    i=0
    while i<len(seq):
        if seq[i]!=9:i+=1;continue
        j=i
        while j<len(seq) and seq[j]==9:j+=1
        if j-i<=3 and ((i==0 or seq[i-1]==4) and (j==len(seq) or seq[j]==4)):
            # both boundaries are either foreground or edge
            for k in range(i,j):
                r,c=coords[k];o[r][c]=2
        i=j
for r in range(R):process(g[r],[(r,c) for c in range(C)])
